const input = $input.first()?.json || {};
const now = input.sim_now ? new Date(input.sim_now) : new Date();
const windowHours = Number(input.window_hours) || 4;
const threshold = Number(input.threshold) || 5;
const cooldownHours = Number(input.cooldown_hours) || 4;
const scenarioSet = input.scenario_set || '';

const windowStart = input.window_start 
  ? new Date(input.window_start) 
  : new Date(now.getTime() - windowHours * 60 * 60 * 1000);

return [{
  json: {
    sim_now: now.toISOString(),
    window_start: windowStart.toISOString(),
    window_hours: windowHours,
    threshold: threshold,
    cooldown_hours: cooldownHours,
    scenario_set: scenarioSet
  }
}];

return [{
  json: {
    status: 'safe',
    message: 'Quét hoàn tất: Không có lô hàng nào vượt ngưỡng cảnh báo (Hệ thống an toàn).',
    timestamp: new Date().toISOString()
  }
}];

const item = $input.first().json;
return [{
  json: {
    status: 'cooldown_suppressed',
    message: `[Cooldown Active] Lô ${item.lot_id} sự cố ${item.issue_type} (${item.cluster_size} ca) đã được cảnh báo trong vòng ${item.cooldown_hours}h qua. Tự động bỏ qua chống gửi trùng.`,
    lot_id: item.lot_id,
    issue_type: item.issue_type,
    cluster_size: item.cluster_size,
    sim_now: item.sim_now
  }
}];

