const item = $input.first().json;
const prior = $("6. Check Cooldown").first().json;

let aiData = {};
try {
  if (item.candidates && item.candidates[0]?.content?.parts?.[0]?.text) {
    const rawText = item.candidates[0].content.parts[0].text;
    aiData = JSON.parse(rawText.replace(/```json/g, "").replace(/```/g, "").trim());
  } else if (item.incident_summary) {
    aiData = item;
  }
} catch (e) {
  aiData = {
    incident_summary: `Phát hiện cụm ${prior.cluster_size} đánh giá phản ánh lỗi ${prior.issue_type} tại lô ${prior.lot_id}.`,
    root_cause_hypothesis: "Nghi ngờ lỗi phát sinh từ khâu đóng gói hoặc đóng thùng vận chuyển.",
    evidence: ["Chi tiết xem trong danh sách review mẫu."],
    severity_level: prior.cluster_size >= prior.threshold * 1.5 ? "CRITICAL" : "HIGH",
    immediate_warehouse_actions: [
      `Tạm dừng xuất hàng đối với lô ${prior.lot_id}`,
      "Kiểm tra chất lượng bao bì và niêm phong các kiện chưa xuất kho",
      "Phản hồi tổ đóng gói để kiểm tra lại quy cách bảo vệ"
    ]
  };
}

const summary = aiData.incident_summary || `Cụm lỗi ${prior.issue_type} vượt ngưỡng tại lô ${prior.lot_id}`;
const rootCause = aiData.root_cause_hypothesis || "Chưa xác định";
const severity = aiData.severity_level || "CRITICAL";
const evidenceList = Array.isArray(aiData.evidence) ? aiData.evidence : [aiData.evidence || ""];
const actions = Array.isArray(aiData.immediate_warehouse_actions) 
  ? aiData.immediate_warehouse_actions 
  : ["Tạm dừng xuất kho lô hàng", "Tiến hành rà soát QC"];

const telegramText = `🚨 [CẢNH BÁO KHỦNG HOẢNG LÔ HÀNG] 🚨\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📦 Lô hàng: ${prior.lot_id} (Sản phẩm: ${prior.product_id})\n` +
  `⚠️ Loại sự cố: ${prior.issue_type}\n` +
  `📊 Số ca ghi nhận: ${prior.cluster_size} review tiêu cực (Ngưỡng: ${prior.threshold})\n` +
  `⏱ Cửa sổ giám sát: ${prior.window_start.substring(0, 16)} ➔ ${prior.sim_now.substring(0, 16)}\n` +
  `🔴 Mức độ: ${severity}\n\n` +
  `🔍 TÓM TẮT SỰ CỐ (AI GEMINI):\n${summary}\n\n` +
  `💡 NGUYÊN NHÂN KHẢ DĨ:\n${rootCause}\n\n` +
  `💬 BẰNG CHỨNG KHÁCH HÀNG:\n${evidenceList.map(e => `• "${e}"`).join("\n")}\n\n` +
  `🛠 HÀNH ĐỘNG KHUYẾN NGHỊ CHO THỦ KHO:\n${actions.map((a, i) => `${i + 1}. ${a}`).join("\n")}\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `Trạng thái: ⏳ Chờ thủ kho xác nhận xử lý`;

return [{
  json: {
    lot_id: prior.lot_id,
    issue_type: prior.issue_type,
    product_id: prior.product_id,
    cluster_size: prior.cluster_size,
    threshold: prior.threshold,
    window_start: prior.window_start,
    window_end: prior.sim_now,
    sim_now: prior.sim_now,
    incident_summary: summary,
    root_cause: rootCause,
    evidence: evidenceList.join(" | "),
    severity: severity,
    status: "alerted",
    telegram_message: telegramText,
    actions_suggested: actions.join("; ")
  }
}];
